import{z as E,x as B,o as t,c as d,q as s,j as l,D as n,d as a,s as o,S as c,b as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"nice 与权重","description":"","frontmatter":{"title":"nice 与权重","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nice-weight.md","filePath":"cs/nice-weight.md","lastUpdated":1791063341000}'),p={name:"cs/nice-weight.md"};function m(A,e,u,D,C,h){const r=B("Mermaid");return t(),d("div",null,[e[2]||(e[2]=s('<h1 id="nice-与权重" tabindex="-1">nice 与权重 <a class="header-anchor" href="#nice-与权重" aria-label="Permalink to &quot;nice 与权重&quot;">​</a></h1><div class="epigraph"><p>nice 是用户能拧的相对权重旋钮：数越大越「客气」，折算后同一墙钟里分到的 CPU 更少。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Love, LKD 对 nice 的整理</footer></div><p><a href="/cs/cfs-vruntime">上一课</a>让调度器比较折算后的虚拟时间。缺口是权重 \\(w_i\\) 从哪来。Unix 把用户接口做成 <strong>nice</strong>：默认 0，范围通常 -20 到 19，映射到内部权重表，再进入 vruntime 增量。本课只钉这层映射与「相对份额」，不把多核负载数写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CFS 的目标是份额 \\(w_i/\\sum w\\)，不是固定优先级抢占。用户不能也不该直接写内核权重整数；nice 提供粗档。同一 nice 的任务彼此仍按 vruntime 公平。缺口不是记账公式，而是：<strong>改 nice 只改增量快慢，不把别人从 CPU 上绝对踢走</strong>（除非实时策略另说）。</p><p><span class="marginnote">nice +19 不是停止运行；可运行集合里若只有它，它仍得全部 CPU。权重是相对的。</span></p><p><span class="marginnote">数字实例：Linux 权重表里 nice 0 对应 1024，每差一档权重乘约 1.25——nice 0 对 nice +5 的权重比约 \\(3121:1024\\)，即同一段时间里前者摊到约 75%、后者约 25% 的 CPU。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查表：nice 越低（更负）权重越大，同样 \\(\\Delta t\\) 里 vruntime 涨得越慢，越容易保持「最小」。权限：降低 nice（更贪）通常要特权，升高（更客气）谁都可以——防止普通人把自己调成实时杀手。本课不把具体表项数字当定律，只要求单调。</p><p><span class="marginnote">直觉类比：nice 档位像合伙出资的股份，不是指挥棒——人人都有份上桌，只是切蛋糕时按股比分。这解释了为什么 +19 也不是「禁跑」：可运行队列里只剩它时，它拿 100%。</span></p>',10)),(t(),l(c,null,{default:n(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NICE%5B%22nice%20%E5%80%BC%22%5D%20--%3E%20W%5B%22%E5%86%85%E9%83%A8%E6%9D%83%E9%87%8D%22%5D%0A%20%20W%20--%3E%20VR%5B%22vruntime%20%E5%A2%9E%E9%87%8F%22%5D%0A%20%20VR%20--%3E%20SHARE%5B%22%E7%9B%B8%E5%AF%B9%20CPU%20%E4%BB%BD%E9%A2%9D%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("p",null,[a("与"),i("a",{href:"/cs/mlfq"},"MLFQ"),a(" 对照：nice 是显式用户意图；MLFQ 档位是内核猜的行为。两者可同时存在于不同系统，本课对象是权重。")],-1)),e[4]||(e[4]=i("h2",{id:"机制",tabindex:"-1"},[a("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=i("p",null,[a("权重让后台编译 "),i("code",null,"nice +10"),a(" 而不必用实时优先级去「压」它：前台仍按更高权重摊时间。指标上，这是公平尺子的加权版，不是周转最优。I/O 型即使 nice 较高，也常因 vruntime 停住而保持响应——与上一课一致。")],-1)),e[6]||(e[6]=i("p",null,"组调度（按 tty 或 cgroup 再摊一层）是后话；本课默认权重在任务一级。",-1)),(t(),l(c,null,{default:n(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E4%BB%BB%E5%8A%A1%20A%EF%BC%9Anice%200%EF%BC%8C%E6%9D%83%E9%87%8D%201024%22%5D%20--%3E%20SUM%5B%22%E6%80%BB%E6%9D%83%E9%87%8D%E7%BA%A6%204145%22%5D%0A%20%20T2%5B%22%E4%BB%BB%E5%8A%A1%20B%EF%BC%9Anice%20%2B5%EF%BC%8C%E6%9D%83%E9%87%8D%E7%BA%A6%203121%22%5D%20--%3E%20SUM%0A%20%20SUM%20--%3E%20SA%5B%22A%20%E6%91%8A%E5%88%B0%E7%BA%A6%2075%25%20CPU%22%5D%0A%20%20SUM%20--%3E%20SB%5B%22B%20%E6%91%8A%E5%88%B0%E7%BA%A6%2025%25%20CPU%22%5D%0A%20%20CH%5B%22%E6%8A%8A%20A%20%E4%B9%9F%E8%B0%83%E5%88%B0%20nice%20%2B5%22%5D%20--%3E%20EQ%5B%22%E4%B8%A4%E6%9D%83%E9%87%8D%E7%9B%B8%E5%90%8C%20%E2%87%92%20%E5%90%84%E6%8B%BF%2050%25%22%5D%0A"})]),fallback:n(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=s('<p>这张图回答：nice 差距怎么折算成份额。CPU 不看 nice 数值本身，而是把各任务权重占总权重的比例当份额——调一个 nice 改变的是比例，不是让谁出局。</p><p><span class="marginnote">常见误区：初学者容易把 nice 当绝对优先级，以为低 nice 会「饿死」别的任务。CFS 里每个可运行任务都分得到时间，nice 只改 vruntime 涨速；能完全抢占的是实时调度类，那是另一套机制。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>SCHED_IDLE</code>、<code>SCHED_BATCH</code> 的全部语义写完，不讨论容器 CPU 限额与 nice 谁说了算的政策冲突。实时优先级不是 nice 的延伸：那是另一套调度类，对照课已经分开。</p><p>后课默认：单核上权重决定份额。多核上每 CPU 一条队列，份额会被队列长度扭曲，除非迁移，下一课讲负载均衡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>nice 映射到权重；份额相对，不是绝对禁跑。</li><li>更负的 nice 让 vruntime 走得更慢。</li><li>跨 CPU 搬任务是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',7))])}const S=E(p,[["render",m]]);export{_ as __pageData,S as default};
